func OpenManagedBundle(bundle Bundle) (*Managed, error) {
	config, err := linkedManagedRuntimeConfig()
	if err != nil {
		return nil, err
	}
	return OpenManagedBundleWithRuntime(bundle, config)
}

// OpenManagedBundleWithRuntime is the explicit non-formal comparison entry.
// The selected runtime is immutable for the Managed lifetime and does not
// alter the model, vector space, prefixes, pooling, normalization or truncation.
func OpenManagedBundleWithRuntime(bundle Bundle, config ManagedRuntimeConfig) (*Managed, error) {
	if !bundle.verified {
		return nil, errors.New("本地向量能力包尚未完成完整性校验")
	}
	if err := validateManagedRuntimeConfig(config); err != nil {
		return nil, err
	}
	managed := &Managed{
		bundle: bundle,
		client: &http.Client{Transport: &http.Transport{Proxy: nil}},
		config: config,
		slots:  make(chan struct{}, config.Parallel),
	}
	managed.idle = sync.NewCond(&managed.mu)
	return managed, nil
}

func linkedManagedRuntimeConfig() (ManagedRuntimeConfig, error) {
	threads, err := strconv.Atoi(managedRuntimeThreads)
	if err != nil {
		return ManagedRuntimeConfig{}, errors.New("本地向量运行时 build threads 无效")
	}
	parallel, err := strconv.Atoi(managedRuntimeParallel)
	if err != nil {
		return ManagedRuntimeConfig{}, errors.New("本地向量运行时 build parallel 无效")
	}
	return ManagedRuntimeConfig{Threads: threads, ThreadsBatch: threads, Parallel: parallel}, nil
}

func validateManagedRuntimeConfig(config ManagedRuntimeConfig) error {
	if config.Threads < 1 || config.Threads > runtime.NumCPU() {
		return fmt.Errorf("本地向量运行时 threads 必须在 1..%d", runtime.NumCPU())
	}
	if config.ThreadsBatch < 1 || config.ThreadsBatch > runtime.NumCPU() {
		return fmt.Errorf("本地向量运行时 threads-batch 必须在 1..%d", runtime.NumCPU())
	}
	if config.Parallel < 1 || config.Parallel > 4 {
		return errors.New("本地向量运行时 parallel 必须在 1..4")
	}
	return nil
}

